2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the server's behavior of halting when it received a message from a service with a mismatched `SystemToken`, which could lead to denial of service and potential exploitation by malicious users. This behavior was inappropriate as it treated invalid system user authentications more severely than regular user authentications, creating a security vulnerability.

        Commit message:
        ACCUMULO-3880 Remove halt on bad SystemToken.

While incorrect SystemTokens might sometimes be
the product of inconsistent system configuration,
it can also be used as an attack vector by
malicious parties. We need to treat invalid
authentications for the system user the same
as regular users (deny them and keep going).  

        Patch:

     private void checkPermission(TCredentials credentials, String lock, final String request) throws ThriftSecurityException {
-      boolean fatal = false;
       try {
         log.debug("Got " + request + " message from user: " + credentials.getPrincipal());
         if (!security.canPerformSystemActions(credentials)) {
           log.warn("Got " + request + " message from user: " + credentials.getPrincipal());
           throw new ThriftSecurityException(credentials.getPrincipal(), SecurityErrorCode.PERMISSION_DENIED);
         }
       } catch (ThriftSecurityException e) {
         log.warn("Got " + request + " message from unauthenticatable user: " + e.getUser());
         if (SystemCredentials.get().getToken().getClass().getName().equals(credentials.getTokenClassName())) {
           log.fatal("Got message from a service with a mismatched configuration. Please ensure a compatible configuration.", e);
-          fatal = true;
         }
         throw e;
-      } finally {
-        if (fatal) {
-          Halt.halt(1, new Runnable() {
-            @Override
-            public void run() {
-              logGCInfo(getSystemConfiguration());
-            }
-          });
-        }
       }

       if (tabletServerLock == null || !tabletServerLock.wasLockAcquired()) {
         log.warn("Got " + request + " message from master before lock acquired, ignoring...");
         throw new RuntimeException("Lock not acquired");
       }

       if (tabletServerLock != null && tabletServerLock.wasLockAcquired() && !tabletServerLock.isLocked()) {
         Halt.halt(1, new Runnable() {
           @Override
           public void run() {
             log.info("Tablet server no longer holds lock during checkPermission() : " + request + ", exiting");
             logGCInfo(getSystemConfiguration());
           }
         });
       }

       if (lock != null) {
         ZooUtil.LockID lid = new ZooUtil.LockID(ZooUtil.getRoot(instance) + Constants.ZMASTER_LOCK, lock);

         try {
           if (!ZooLock.isLockHeld(masterLockCache, lid)) {
             // maybe the cache is out of date and a new master holds the
             // lock?
             masterLockCache.clear();
             if (!ZooLock.isLockHeld(masterLockCache, lid)) {
               log.warn("Got " + request + " message from a master that does not hold the current lock " + lock);
               throw new RuntimeException("bad master lock");
             }
           }
         } catch (Exception e) {
           throw new RuntimeException("bad master lock", e);
         }
       }
     }



